import{_ as s,o as i,c as a,a5 as r}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Verification plan","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-trend-source-config/test.md","filePath":"feature/admin-trend-source-config/test.md"}'),t={name:"feature/admin-trend-source-config/test.md"};function n(o,e,l,c,d,u){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="verification-plan" tabindex="-1">Verification plan <a class="header-anchor" href="#verification-plan" aria-label="Permalink to &quot;Verification plan&quot;">​</a></h1><ul><li>Defaults retain all existing page/group sources and 50 posts (or valid env override).</li><li>Canonicalize facebook.com/www/m hosts, trailing slash and profile.php?id numeric. Reject non-HTTPS, credentials/ports, arbitrary subdomains, posts/videos/share URLs, encoded traversal, unsafe IDs, duplicates (including aliases), empty and &gt;50 lists, boolean/fraction/out-of-range limits, invalid and stale revisions.</li><li>Simultaneous writes with same revision: one succeeds, one conflicts. Atomic file replacement never yields partial JSON. Corrupt saved settings block, no default fallback.</li><li>Manual start freezes settings before subprocess; schedule/default wrapper uses same store. Saving next config cannot change current snapshot. CLI explicit source/max flags remain honored. Recovery receives no new source config.</li><li>Manifest retains source count, snapshot revision and max posts; downstream queue, batch, closure, aggregation, graph/vector writes and cron are unchanged.</li><li>API internal auth and Business Admin guard reject before store/upstream access; invalid DTO, stale revision and unavailable storage are safe 400/409/503, successful save audited once. No secrets or filesystem paths returned.</li><li>Mocked browser: expand, direct edit/save/cancel, numeric validation, dirty input survives polling, double-save prevented, 409 explicit reload, loading/503 retry, saved total, no start-run request, keyboard labels, vi/en/light/dark and 375px.</li><li>Native pipeline/recovery regressions; Business compile; Web lint/build. No live setting write, crawl, paid AI, database migration or seed during QA.</li></ul><h2 id="results-—-2026-10-30" tabindex="-1">Results — 2026-10-30 <a class="header-anchor" href="#results-—-2026-10-30" aria-label="Permalink to &quot;Results — 2026-10-30&quot;">​</a></h2><ul><li>38 source-config checks passed: defaults (10 shipped pages + 1 group), env, aliases, malformed URLs, duplicate identities/output names, bounds, revision races, atomic replacement, corrupt-store refusal, snapshot immutability, explicit CLI overrides, scheduled wrapper/manual argv and untouched recovery. FastAPI tests verified internal auth and safe 400/409/503 with temporary files.</li><li>36 existing native pipeline/recovery regression checks passed. Dummy runner fixture now includes source defaults; real Facebook/browser/provider never invoked.</li><li>Business compile passed. Mockito smoke verified requireAdmin before upstream, payload, successful save audit, validation and structured 400/409/503 mapping; existing recovery smoke also passed. No DB connection or real audit writes.</li><li>Web npm run ci passed (existing repository warnings remain); changed component, hook, service and type lint passed. Mocked real browser passed source editing, totals, inline bounds, keyboard save, pending/double-click protection, dirty input retained through pipeline refresh/collapse, 409 explicit reload, GET/PATCH 503, undo and vi/en/light/dark at 375/768/1440px. Screenshots inspected; explicit foreground classes fix shared native field/ghost-button dark-mode inheritance. Expected mock error responses only, no page exceptions or horizontal overflow.</li><li>All executable QA/screenshots/logs remain ignored in keep-local-only. The actual deployment&#39;s source list, max posts, schedule and business DBs were not changed.</li></ul><h2 id="rollout-and-manual-check" tabindex="-1">Rollout and manual check <a class="header-anchor" href="#rollout-and-manual-check" aria-label="Permalink to &quot;Rollout and manual check&quot;">​</a></h2><ol><li>Restart Business and AI Service, and restart the crawler scheduler if used. Do not start the scheduler merely to test the settings UI: it can trigger crawling.</li><li>Admin &gt; Trends &gt; Trend pipeline &gt; Nguồn crawl và số bài. Current defaults show the existing 11 sources and 50 posts/source unless FB_MAX_POSTS overrides it. Edit URLs/limit and save; this alone does not launch a crawl.</li><li>The next normal manual/scheduled run freezes settings. Check its native manifest source_config_revision, max_posts_per_source and planned_sources. Sources use the existing browser/queue/worker/DB flow. A recovery does not read new settings.</li><li>Durable configuration is social_crawler/keep-local-only/crawl-control/source-config.json; snapshots are in config-snapshots/. Preserve this runtime directory across redeployments and share it between API and scheduler; do not commit it or treat it as disposable QA. A multi-host setup needs shared storage. No migration, init/seeder edits, source-file rewrite or data cleanup is required.</li></ol>',6)])])}const m=s(t,[["render",n]]);export{h as __pageData,m as default};
